CREATE ROLE anon NOLOGIN;CREATE ROLE authenticated NOLOGIN;CREATE ROLE service_role NOLOGIN BYPASSRLS;
GRANT anon,authenticated,service_role TO postgres;
CREATE SCHEMA auth;CREATE TABLE auth.users(id uuid PRIMARY KEY,email text,raw_user_meta_data jsonb DEFAULT '{}',raw_app_meta_data jsonb DEFAULT '{}');
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid $$;
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id),email text NOT NULL,full_name text NOT NULL,role text NOT NULL DEFAULT 'student',phone text,avatar_url text,created_at timestamptz DEFAULT now(),banned boolean DEFAULT false,is_banned boolean DEFAULT false,verification_status text DEFAULT 'unverified',username text,verification_paid boolean DEFAULT false,verification_payment_ref text,verified_at timestamptz,verified_by uuid,id_document_url text,id_document_back_url text,selfie_url text,property_document_url text,id_document_type text,nin_number text,verification_type text);
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND role IN ('admin','super_admin')) $$;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY legacy_profiles_read ON public.profiles FOR SELECT USING(true);
CREATE POLICY profiles_owner_write ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.listings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),landlord_id uuid REFERENCES public.profiles(id),title text NOT NULL DEFAULT 'Test room',description text,room_type text NOT NULL DEFAULT 'self_con',price_yearly integer NOT NULL,distance_from_gate text DEFAULT 'under_5',address text DEFAULT '',area text DEFAULT '',university text DEFAULT 'uniport',landmark text,amenities text[] DEFAULT '{}',photos text[] DEFAULT '{}',status text NOT NULL DEFAULT 'pending',is_featured boolean DEFAULT false,show_on_home boolean DEFAULT false,is_urgent boolean DEFAULT false,agent_fee_type text DEFAULT 'none',agent_fee_amount numeric,occupancy integer DEFAULT 1,whatsapp_number text DEFAULT '',phone_number text,available_from timestamptz,video_url text,views_count integer DEFAULT 0,created_at timestamptz DEFAULT now());
ALTER TABLE public.listings ENABLE ROW LEVEL SECURITY;
CREATE POLICY current_listings_public ON public.listings FOR SELECT USING(status='active' OR landlord_id=auth.uid() OR public.is_admin());
CREATE POLICY owner_listings_update ON public.listings FOR UPDATE USING(landlord_id=auth.uid()) WITH CHECK(landlord_id=auth.uid());
CREATE TABLE public.roommate_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES public.profiles(id),status text DEFAULT 'active',university text,phone_number text,budget_min integer,budget_max integer,gender text,preferred_gender text,bio text,lifestyle_tags jsonb DEFAULT '[]',room_address text,room_photos text[] DEFAULT '{}',intent text,target_listing_id uuid REFERENCES public.listings(id),target_listing_title text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
ALTER TABLE public.roommate_profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.service_providers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES public.profiles(id),status text DEFAULT 'active',business_name text,category text,university text,whatsapp_number text,created_at timestamptz DEFAULT now());
CREATE TABLE public.platform_settings(key text PRIMARY KEY,value text);INSERT INTO public.platform_settings VALUES('maintenance_mode','false');
CREATE TABLE public.reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),listing_id uuid REFERENCES public.listings(id),rating integer,reviewer_name text,review_text text,created_at timestamptz DEFAULT now());
GRANT USAGE ON SCHEMA auth,public TO anon,authenticated,service_role;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO anon,authenticated,service_role;
-- Compatibility fixture for the audited schema: no production records or credentials.
ALTER TABLE public.profiles ADD COLUMN verification_note text,ADD COLUMN ndpa_consent boolean DEFAULT false,ADD COLUMN ndpa_consent_at timestamptz,ADD COLUMN marketing_opt_in boolean DEFAULT false;
CREATE TABLE public.subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),landlord_id uuid UNIQUE REFERENCES public.profiles(id),plan text,active boolean,is_trial boolean,billing_cycle text,amount_paid integer,expires_at timestamptz,paystack_reference text);
CREATE TABLE public.trial_phone_registry(phone text PRIMARY KEY);
CREATE TABLE public.trial_email_registry(email text PRIMARY KEY);
CREATE TABLE public.payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),landlord_id uuid REFERENCES public.profiles(id),type text,plan text,billing_cycle text,listing_id uuid REFERENCES public.listings(id),boost_type text,amount integer,paystack_reference text UNIQUE,status text DEFAULT 'pending',created_at timestamptz DEFAULT now());
CREATE TABLE public.listing_boosts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),listing_id uuid REFERENCES public.listings(id),landlord_id uuid REFERENCES public.profiles(id),boost_type text,active boolean,starts_at timestamptz,expires_at timestamptz,paystack_reference text);
CREATE TABLE public.university_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),university_name text,campus_area text,role text,contact_info text,created_at timestamptz DEFAULT now());
ALTER TABLE public.university_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow admin select on university_requests" ON public.university_requests FOR SELECT TO authenticated USING(public.is_admin());
CREATE VIEW public.university_requests_summary AS SELECT university_name AS normalized_name,count(*)::int AS total_requests,count(*)::int AS student_requests,0::int AS landlord_requests,count(DISTINCT contact_info)::int AS unique_contacts,max(created_at) AS last_requested_at,array_agg(campus_area) AS reported_areas FROM public.university_requests GROUP BY university_name;
CREATE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NEW;END $$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE FUNCTION public.expire_listing_boosts() RETURNS void LANGUAGE plpgsql AS $$ BEGIN RETURN;END $$;
CREATE FUNCTION public.sync_featured_listings() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NEW;END $$;
CREATE FUNCTION public.generate_username(text) RETURNS text LANGUAGE sql AS $$ SELECT $1 $$;
CREATE FUNCTION public.increment_service_stat(uuid,text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN RETURN;END $$;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO anon,authenticated,service_role;
GRANT ALL ON ALL TABLES IN SCHEMA auth TO service_role;

ALTER TABLE public.service_providers ADD COLUMN is_verified boolean DEFAULT false,ADD COLUMN listing_paid boolean DEFAULT false,ADD COLUMN is_boosted boolean DEFAULT false,ADD COLUMN listing_expires_at timestamptz,ADD COLUMN boost_type text,ADD COLUMN boost_expires_at timestamptz;
